```ts
export interface SuccessCaseResubmission {
  readonly resubmissionId: string;
  readonly incidentId: string;
  readonly oldCaseVersionId: string;
  readonly source:
    | NaturalLanguageSource
    | FormattedCaseSource
    | VideoSource;
